*** Begin Patch
*** Delete File: package.json
*** Add File: package.json
+{
+  \"name\": \"folio-bookshelf\",
+  \"private\": true,
+  \"type\": \"module\",
+  \"scripts\": {
+    \"dev\": \"node server.js\",
+    \"start\": \"node server.js\",
+    \"build\": \"node --check server.js && node --check public/app.js\",
+    \"test\": \"vitest run\"
+  },
+  \"devDependencies\": {
+    \"vitest\": \""'^3.1.3"
+  }
+}
*** Add File: server.js
+import { createServer } from '"'node:http';
+import { readFile, writeFile, rename, mkdir, unlink } from 'node:fs/promises';
+import { dirname, join, resolve } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { randomUUID } from 'node:crypto';
+
+const root = dirname(fileURLToPath(import.meta.url));
+const publicDirectory = join(root, 'public');
+const defaultDataFile = join(root, 'data', 'books.json');
+
+class HttpError extends Error {
+  constructor(status, message) {
+    super(message);
+    this.status = status;
+  }
+}
+
+async function readBooks(dataFile) {
+  try {
+    const books = JSON.parse(await readFile(dataFile, 'utf8'));
+    if ("'!Array.isArray(books)) throw new Error('"'Books file must contain an array');
+    return books;
+  } catch (error) {
+    if (error.code === 'ENOENT') return [];
+    throw error;
+  }
+}
+
+async function saveBooks(dataFile, books) {
+  await mkdir(dirname(dataFile), { recursive: true });
+  const temporaryFile = "'`${dataFile}.${randomUUID()}.tmp`;
+  try {
+    await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}'"\\n"'`, '"'utf8');
+    await rename(temporaryFile, dataFile);
+  } catch (error) {
+    await unlink(temporaryFile).catch(() => {});
+    throw error;
+  }
+}
+
+async function readBody(request) {
+  let text = '';
+  for await (const chunk of request) {
+    text += chunk;
+    if (text.length > 65536) throw new HttpError(413, 'Request is too large.');
+  }
+  try {
+    const value = JSON.parse(text);
+    if ("'!value || typeof value !== '"'object' || Array.isArray(value)) throw new Error();
+    return value;
+  } catch {
+    throw new HttpError(400, 'Please send a valid JSON object.');
+  }
+}
+
+function sendJson(response, status, value) {
+  response.writeHead(status, {
+    'Content-Type': 'application/json; charset=utf-8',
+    'Cache-Control': 'no-store',
+  });
+  response.end(JSON.stringify(value));
+}
+
+async function sendPage(response, filename, contentType) {
+  const contents = await readFile(join(publicDirectory, filename));
+  response.writeHead(200, { 'Content-Type': contentType, 'Cache-Control': 'no-store' });
+  response.end(contents);
+}
+
+function validateBook(body) {
+  const title = typeof body.title === 'string' ? body.title.trim() : '';
+  const author = typeof body.author === 'string' ? body.author.trim() : '';
+  const notes = typeof body.notes === 'string' ? body.notes.trim() : '';
+  if ("'!title || !author) throw new HttpError(400, '"'Title and author are required.');
+  if (title.length > 160 || author.length > 120 || notes.length > 5000) {
+    throw new HttpError(400, 'One of your entries is too long.');
+  }
+  return { title, author, notes };
+}
+
+export function createAppServer({ dataFile = process.env.BOOKS_FILE || defaultDataFile } = {}) {
+  let pendingMutation = Promise.resolve();
+
+  function mutate(update) {
+    const operation = pendingMutation.then(async () => {
+      const books = await readBooks(dataFile);
+      const result = update(books);
+      await saveBooks(dataFile, books);
+      return result;
+    });
+    pendingMutation = operation.catch(() => {});
+    return operation;
+  }
+
+  return createServer(async (request, response) => {
+    try {
+      const pathname = new URL(request.url, 'http://localhost').pathname;
+      const bookRoute = pathname.match(/"'^'"\\/api\\/books\\/([a-zA-Z0-9-]+)"'$/);
+
+      if (pathname === '"'/api/books' && request.method === 'GET') {
+        return sendJson(response, 200, await readBooks(dataFile));
+      }
+      if (pathname === '/api/books' && request.method === 'POST') {
+        const fields = validateBook(await readBody(request));
+        const book = await mutate((books) => {
+          const newBook = {
+            id: randomUUID(),
+            ...fields,
+            status: 'reading',
+            createdAt: new Date().toISOString(),
+            finishedAt: null,
+          };
+          books.push(newBook);
+          return newBook;
+        });
+        return sendJson(response, 201, book);
+      }
+      if (bookRoute && request.method === 'GET') {
+        const book = (await readBooks(dataFile)).find((item) => item.id === bookRoute[1]);
+        if ("'!book) throw new HttpError(404, '"'Book not found.');
+        return sendJson(response, 200, book);
+      }
+      if (bookRoute && request.method === 'PATCH') {
+        const { status } = await readBody(request);
+        if (status "'!== '"'reading' && status "'!== '"'finished') {
+          throw new HttpError(400, 'Status must be reading or finished.');
+        }
+        const book = await mutate((books) => {
+          const found = books.find((item) => item.id === bookRoute[1]);
+          if ("'!found) throw new HttpError(404, '"'Book not found.');
+          found.status = status;
+          found.finishedAt = status === 'finished' ? new Date().toISOString() : null;
+          return found;
+        });
+        return sendJson(response, 200, book);
+      }
+      if (bookRoute && request.method === 'DELETE') {
+        await mutate((books) => {
+          const index = books.findIndex((item) => item.id === bookRoute[1]);
+          if (index === -1) throw new HttpError(404, 'Book not found.');
+          books.splice(index, 1);
+        });
+        response.writeHead(204);
+        return response.end();
+      }
+      if (request.method === 'GET') {
+        if (pathname === '/styles.css') return await sendPage(response, 'styles.css', 'text/css; charset=utf-8');
+        if (pathname === '/app.js') return await sendPage(response, 'app.js', 'text/javascript; charset=utf-8');
+        if (pathname === '/favicon.svg') return await sendPage(response, 'favicon.svg', 'image/svg+xml');
+        if (pathname === '/' || /"'^'"\\/books\\/[a-zA-Z0-9-]+"'$/.test(pathname)) {
+          return await sendPage(response, '"'index.html', 'text/html; charset=utf-8');
+        }
+      }
+      throw new HttpError(404, 'Page not found.');
+    } catch (error) {
+      if ("'!(error instanceof HttpError)) console.error(error);
+      if (!response.headersSent) {
+        sendJson(response, error.status || 500, { error: error.status ? error.message : '"'Something went wrong.' });
+      }
+    }
+  });
+}
+
+if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
+  const port = Number(process.env.PORT) || 3000;
+  createAppServer().listen(port, '0.0.0.0', () => {
+    console.log("'`Folio is ready at http://localhost:${port}`);
+  });
+}
