/bin/bash -c "apply_patch <<'PATCH'
*** Begin Patch
*** Add File: public/styles.css
+:root {
+  color-scheme: light;
+  --forest: #193e33;
+  --forest-dark: #123328;
+  --ink: #263c34;
+  --muted: #7b827a;
+  --line: #e9e8df;
+  --paper: #fbfaf7;
+  --rail: #f3f1e9;
+  --gold: #c3a96b;
+  font-family: \"Avenir Next\", Avenir, \"Segoe UI\", sans-serif;
+  font-synthesis: none;
+}
+
+* { box-sizing: border-box; }
+html { scroll-behavior: smooth; }
+body { margin: 0; background: var(--paper); color: var(--ink); }
+button, input, textarea { font: inherit; }
+button { cursor: pointer; }
+a { color: inherit; text-decoration: none; }
+button:focus-visible, a:focus-visible, input:focus-visible, textarea:focus-visible { outline: 3px solid #c2a969; outline-offset: 3px; }
+.icon { width: 19px; height: 19px; flex: none; }
+.loading-screen, .load-error { min-height: 100vh; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 30px; color: var(--forest); }
+.load-error h1 { font: 42px/1.1 Georgia, serif; }
+.load-error p { color: var(--muted); margin-bottom: 22px; }
+
+.app-shell { display: grid; grid-template-columns: 234px minmax(0, 1fr); min-height: 100vh; }
+.sidebar { position: sticky; top: 0; align-self: start; display: flex; flex-direction: column; height: 100vh; min-height: 650px; padding: 36px 19px 27px; color: #f6f3e8; background: var(--forest); overflow: hidden; }
+.brand { display: flex; align-items: center; gap: 12px; width: fit-content; padding-left: 13px; font: 600 32px/.9 Georgia, serif; letter-spacing: -2px; }
+.brand__period { color: #d7ba78; }
+.brand__symbol { display: grid; width: 36px; height: 36px; place-items: center; border: 1px solid rgba(238, 232, 208, .55); border-radius: 8px; transform: rotate(-7deg); }
+.brand__symbol .icon { width: 24px; height: 24px; stroke-width: 1.45; }
+.sidebar__inner { margin-top: 81px; }
+.sidebar__label { margin: 0 0 19px 15px; color: #a5baaa; font-size: 10px; font-weight: 700; letter-spacing: 2.1px; }
+.sidebar__nav { display: grid; gap: 8px; }
+.nav-link { display: flex; align-items: center; gap: 13px; min-height: 47px; padding: 0 13px; border-radius: 8px; color: #c0cec2; font-size: 13px; font-weight: 550; white-space: nowrap; transition: background .2s, color .2s; }
+.nav-link:hover { background: #2a5245; color: white; }
+.nav-link.is-active { background: #315749; color: #fffdf4; }
+.nav-link .icon { width: 17px; height: 17px; }
+.nav-link__count { margin-left: auto; color: #b6c7b8; font-size: 11px; }
+.sidebar__bottom { margin-top: auto; padding: 0 15px; }
