+    expect(finished.status).toBe('finished');
+    expect(finished.finishedAt).toBeTruthy();
+
+    const annotated = await (await sendJson("'`${url}/api/books/${book.id}`, '"'PATCH', { notes: '  Desert planet.  ' })).json();
+    expect(annotated.notes).toBe('Desert planet.');
+    expect(annotated.status).toBe('finished');
+
+    const reading = await (await sendJson("'`${url}/api/books/${book.id}`, '"'PATCH', { status: 'reading' })).json();
