/bin/bash -c "node --input-type=module <<'NODE'
import { readFile } from 'node:fs/promises';
const books = JSON.parse(await readFile('./data/books.json', 'utf8'));
const app = { innerHTML: '' };
const toast = { textContent: '', classList: { add() {}, remove() {} } };
globalThis.document = {
  title: '',
  querySelector(selector) { return selector === '#app' ? app : toast; },
  addEventListener() {},
};
globalThis.location = { pathname: '/', hash: '', origin: 'http://localhost:3000' };
globalThis.fetch = async (path) => ({ ok: true, json: async () => path === '/api/books' ? books : books.find((book) => path.endsWith(book.id)) });
await import('./public/app.js?home');
await new Promise((resolve) => setTimeout(resolve, 10));
if ("'!app.innerHTML.includes('"'Currently reading') || "'!app.innerHTML.includes('"'Finished books') || "'!app.innerHTML.includes('"'The Creative Act')) throw new Error('Home rendering failed');
console.log('Home render: OK');
globalThis.location.pathname = '/books/the-creative-act';
await import('./public/app.js?detail');
await new Promise((resolve) => setTimeout(resolve, 10));
if ("'!app.innerHTML.includes('"'Your notes') || "'!app.innerHTML.includes('"'Copy book link') || "'!app.innerHTML.includes('"'Rick Rubin')) throw new Error('Detail rendering failed');
console.log('Direct detail render: OK');
NODE
